{
  "name": "Triton 200低温制冷系统",
  "name_en": "Triton 200 Cryogenic Refrigeration System",
  "manufacturer": "Oxford Instruments",
  "description": "用于超低温实验的Triton 200低温制冷系统，可读取Cernox或RuO2温度通道、设置温度设定值、更新加热器、执行受控升降温，并控制涡轮泵等低温系统部件。",
  "description_en": "The Triton 200 is a cryogenic refrigeration system for ultra-low-temperature experiments. It supports reading Cernox or RuO2 temperature channels, setting temperature setpoints, updating heater behavior, running controlled temperature ramps, and controlling subsystems such as a turbo pump.",
  "tag_hints": [
    "cryogenic system",
    "ultra-low temperature",
    "temperature control",
    "dilution refrigerator",
    "heater control",
    "turbo pump",
    "Cernox sensor",
    "RuO2 sensor"
  ],
  "actions": [
    {
      "action_name": "auto-controlled_ramp_off",
      "description": "停止当前温度通道的受控温度扫描。",
      "description_en": "Stop a controlled temperature sweep on the current temperature channel."
    },
    {
      "action_name": "auto-controlled_ramp_on",
      "description": "启动当前温度通道的受控温度扫描。",
      "description_en": "Start a controlled temperature sweep on the current temperature channel."
    },
    {
      "action_name": "auto-query_and_receive",
      "description": "向Triton 200发送原始查询命令并接收响应。",
      "description_en": "Send a raw query command to the Triton 200 and receive the response."
    },
    {
      "action_name": "auto-temperature_channel",
      "description": "获取/设置温度通道（Cernox 5或RuO2 6）。",
      "description_en": "Get/set the temperature channel (Cernox 5 or RuO2 6)."
    },
    {
      "action_name": "auto-temperature_setpoint",
      "description": "获取/设置温度设定值。",
      "description_en": "Get/set the temperature setpoint."
    },
    {
      "action_name": "auto-turbo_off",
      "description": "关闭涡轮泵。",
      "description_en": "Turn off the turbo pump."
    },
    {
      "action_name": "auto-turbo_on",
      "description": "开启涡轮泵。",
      "description_en": "Turn on the turbo pump."
    },
    {
      "action_name": "auto-update_heater",
      "description": "将加热器关联到当前温度通道，并按当前温度设定值更新加热电流。",
      "description_en": "Associate the heater with the current temperature channel and update the heater current according to the current temperature setpoint."
    },
    {
      "action_name": "auto-temperature",
      "description": "获取当前温度通道的温度读数。",
      "description_en": "Get the temperature reading from the current temperature channel."
    },
    {
      "action_name": "auto-extract_value",
      "description": "从设备响应中提取指定名词和单位对应的数值。",
      "description_en": "Extract the value corresponding to a specified noun and unit from a device response."
    }
  ]
}

